class Frame:
    def __init__(self, rows):
        self.rows = rows
    def drop_duplicates(self, subset):
        key = subset[0]
        seen = set()
        result = []
        for row in self.rows:
            if row[key] in seen:
                continue
            seen.add(row[key])
            result.append(row)
        return result

