class Conn:
    def __init__(self, fail_second=False):
        self.fail_second = fail_second
        self.calls = 0
        self.events = []
    def execute(self, name):
        self.calls += 1
        if self.fail_second and self.calls == 2:
            raise Exception("write2 failed")
        self.events.append(name)
    def rollback(self):
        self.events.append("rollback")
    def commit(self):
        self.events.append("commit")

def save(conn):
    try:
        conn.execute("write1")
        conn.execute("write2")
    except Exception:
        conn.rollback()
        raise
    else:
        conn.commit()

conn = Conn(fail_second=False)
save(conn)
print(conn.events)

